class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    void speak() {
        System.out.println(name + "：……");
    }
}

class Cat extends Animal {
    Cat(String name) {
        super(name);
    }

    void sleep() {
        System.out.println(name + "睡着了，呼噜呼噜");
    }
}

public class Main {
    public static void main(String[] args) {
        Animal a = new Cat("{name}");
        if (a instanceof Cat) {
            Cat c = (Cat) a;
            c.sleep();
        }
    }
}
